import sys

def isWordExist(board, word):
    def dfs(x, y, index):
        if index == len(word):
            return True
        if x < 0 or x >= len(board) or y < 0 or y >= len(board[0]) or board[x][y] != word[index]:
            return False
        temp, board[x][y] = board[x][y], '#'
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            if dfs(x + dx, y + dy, index + 1):
                return True
        board[x][y] = temp
        return False

    for i in range(len(board)):
        for j in range(len(board[0])):
            if dfs(i, j, 0):
                return True
    return False

input = sys.stdin.read().strip().split('\n')
board = [list(row.strip()) for row in input[:-1]]
word = input[-1].strip()
print('1' if isWordExist(board, word) else '0')
